-- The Salesforce accounts report, joined onto the canonical client list, so
-- /clients can show health, products, EHR, segment and the contract facts per
-- account instead of just a name.
--
-- Source: "Accounts Report for Product Requirements", 2026-08-18, filtered to
-- active direct accounts. That filter is why 21 of the 95 accounts keep NULLs
-- here and render as "-" rather than as a data bug.

-- AlterTable
ALTER TABLE "Account" ADD COLUMN     "accountOwner" TEXT,
ADD COLUMN     "arr" INTEGER,
ADD COLUMN     "billingState" TEXT,
ADD COLUMN     "carr" INTEGER,
ADD COLUMN     "csmName" TEXT,
ADD COLUMN     "ehr" TEXT,
ADD COLUMN     "firstClosedWon" TIMESTAMP(3),
ADD COLUMN     "health" TEXT,
ADD COLUMN     "hieMembers" INTEGER,
ADD COLUMN     "lastActivityAt" TIMESTAMP(3),
ADD COLUMN     "liveDate" TIMESTAMP(3),
ADD COLUMN     "products" TEXT NOT NULL DEFAULT '[]',
ADD COLUMN     "qualityMembers" INTEGER,
ADD COLUMN     "renewalDate" TIMESTAMP(3),
ADD COLUMN     "riskMembers" INTEGER,
ADD COLUMN     "segment" TEXT;

-- Fill in the 74 accounts the report covers. Matched on the canonical display
-- name, so a row the report still labels "Tufts Medicine (FKA Wellforce)" lands
-- on "Tufts Medicine" rather than missing.
UPDATE "Account" a SET
  "health"         = v.health,
  "products"       = v.products,
  "ehr"            = v.ehr,
  "segment"        = v.segment,
  "billingState"   = v.billing_state,
  "accountOwner"   = v.account_owner,
  "csmName"        = v.csm_name,
  "hieMembers"     = v.hie_members::int,
  "qualityMembers" = v.quality_members::int,
  "riskMembers"    = v.risk_members::int,
  "arr"            = v.arr::int,
  "carr"           = v.carr::int,
  "renewalDate"    = v.renewal_date::timestamp,
  "lastActivityAt" = v.last_activity::timestamp,
  "firstClosedWon" = v.first_closed_won::timestamp
